<?php
namespace App\Http\Controllers;
use App\Models\Inquiry; use App\Models\Property; use App\Models\Report; use App\Models\User; use App\Services\DashboardStatistics; use Illuminate\Http\Request; use Illuminate\Support\Facades\Cache;
class PropertyController extends Controller {
 public function landing(){ $top=Property::where('status','published')->latest('published_at')->take(6)->get(); $offers=Property::where('status','published')->where('reward_available',true)->latest()->take(3)->get(); $stats=Cache::remember('home:stats',now()->addMinutes(5),fn()=>['properties'=>Property::where('status','published')->count(),'owners'=>User::where('role','owner')->count()]); return view('home',compact('top','offers','stats')); }
 public function index(Request $request){$query=Property::with('owner')->where('status','published')->when($request->city,fn($q,$v)=>$q->where('city',$v))->when($request->neighborhood,fn($q,$v)=>$q->where('neighborhood','like','%'.$v.'%'))->when($request->purpose,fn($q,$v)=>$q->where('purpose',$v))->when($request->category,fn($q,$v)=>$q->where('category',$v))->when($request->min_price,fn($q,$v)=>$q->where('price','>=',$v))->when($request->max_price,fn($q,$v)=>$q->where('price','<=',$v))->when($request->min_area,fn($q,$v)=>$q->where('area','>=',$v))->when($request->max_area,fn($q,$v)=>$q->where('area','<=',$v))->when($request->bedrooms,fn($q,$v)=>$q->where('bedrooms','>=',$v))->when($request->bathrooms,fn($q,$v)=>$q->where('bathrooms','>=',$v))->when($request->floor,fn($q,$v)=>$q->where('floor',$v))->when($request->furnished!==null&&$request->furnished!=='',fn($q)=>$q->where('furnished',(bool)$request->furnished))->when($request->reward!==null&&$request->reward!=='',fn($q)=>$q->where('reward_available',(bool)$request->reward));$sort=$request->input('sort','latest');$sort==='price_low'?$query->orderBy('price'):($sort==='price_high'?$query->orderByDesc('price'):$query->latest('published_at'));$properties=$query->paginate(12)->withQueryString();$cities=Property::where('status','published')->select('city')->distinct()->orderBy('city')->pluck('city');$neighborhoods=Property::where('status','published')->select('neighborhood')->distinct()->orderBy('neighborhood')->pluck('neighborhood');return view('properties.index',compact('properties','cities','neighborhoods'));}
 public function show(Property $property){abort_unless($property->status==='published',404);$property->load('owner');return view('properties.show',compact('property'));}
 public function contact(Request $r,Property $property){$d=$r->validate(['phone'=>['required','string','min:8','max:30'],'message'=>['nullable','string','max:1000']]);Inquiry::create(['property_id'=>$property->id,'user_id'=>auth()->id(),'phone'=>$d['phone'],'message'=>$d['message']??null]);DashboardStatistics::forget($property->user_id);return back()->with('success',__('تم تسجيل طلب التواصل. سيتواصل المالك معك مباشرة.'));}
 public function report(Request $r,Property $property){$d=$r->validate(['type'=>'required|in:old,suspicious,impersonation,other','details'=>'nullable|string|max:1000']);Report::create(['property_id'=>$property->id,'reporter_id'=>auth()->id(),'type'=>$d['type'],'details'=>$d['details']??null]);DashboardStatistics::forget();return back()->with('success',__('شكرًا، وصل البلاغ وسيتم مراجعته.'));}
}
